  function sectorBenefitLabel(g,tier,compact=false){const bonuses=g.balance?.sectorBonuses||{},rentPercent=Math.round(((bonuses.rentMultiplier||1)-1)*100),score=bonuses.scoreBonus||0;if(tier<=0)return compact?"未进入":"尚未参与这个板块的项目";if(tier===1)return compact?"已入局":"点亮板块进度";if(tier===2)return compact?`分红+${rentPercent}%`:`本板块项目到访分红 +${rentPercent}%`;if(tier===3)return compact?"解锁3级":"本板块项目可建设至 3 级";return compact?`城市分+${score}`:`结算城市分 +${score}`}
